int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    struct hstate *h;
    unsigned long mask;
    unsigned long start, next;
    int ret = 0;

    h = hstate_addr_to_hstate(addr);
    mask = huge_page_mask(h);

    for (start = addr; start < end; start = next) {
        next = (start + HPAGE_SIZE(h)) & (mask);
        if (next > end)
            next = end;

        if (walk->vma && walk->vma->vm_flags & VM_HUGETLB) {
            ret = walk->pmd_entry(start, walk->vma, walk->private, walk);
            if (ret < 0)
                break;
        } else {
            ret = -EFAULT;
            break;
        }
    }

    return ret;
}

int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    struct hstate *h;
    unsigned long mask;
    unsigned long next;
    int ret = 0;

    h = hstate_file(walk->vma->vm_file->f_mapping);
    if (!h)
        return -EINVAL;

    mask = huge_page_mask(h);
    addr &= mask;
    end = (end + mask) & mask;

    for (; addr < end; addr = next) {
        next = addr + (1UL << h->order);
        if (walk->vma->vm_ops && walk->vma->vm_ops->hugepages) {
            ret = walk->vma->vm_ops->hugepages(walk->vma, addr, walk);
            if (ret)
                break;
        }
    }

    return ret;
}

int walk_huge_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    while (addr < end) {
        unsigned long next;
        struct hstate *h;
        unsigned long mask;

        h = hstate_addr(addr);
        if (!h)
            return -EFAULT;

        mask = huge_page_mask(h);
        next = (addr + (1UL << h->order)) & mask;
        if (next <= addr)
            next = addr + (1UL << h->order);

        if (walk->vma && walk->vma->vm_flags & VM_HUGETLB) {
            int ret = walk->pte_hole(walk, addr, next);
            if (ret)
                return ret;
        }

        addr = next;
    }

    return 0;
}

int walk_huge_page_range(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    int ret = 0;
    struct hstate *h;
    unsigned long mask, next;
    unsigned long sz = huge_page_size(h);
    unsigned long boundary = ALIGN(end, sz);

    for (; addr < boundary; addr = next) {
        next = addr + sz;

        if (addr >= end)
            break;

        mask = huge_page_mask(h);
        if ((addr & mask) != (next & mask)) {
            ret = walk->hfn(addr, next, walk);
            if (ret)
                break;
        }
    }

    return ret;
}

int walk_huge_pages(unsigned long addr, unsigned long end, struct mm_walk *walk) {
    struct hstate *h;
    unsigned long mask;

    for (h = hstate_alloc(); h; h = hstate_next(h)) {
        mask = huge_page_mask(h);
        if (mask == 0)
            continue;

        while (addr < end) {
            unsigned long pfn = addr_to_pfn(addr);
            int ret;

            if ((addr & mask) != addr) {
                addr = (addr & mask) + mask;
                continue;
            }

            ret = walk->vma->ops->fault(walk->vma, addr, pfn);
            if (ret < 0)
                return ret;

            addr += PAGE_SIZE;
        }
    }

    return 0;
}
